    /**
     * @method
     * @name krakenfutures#watchBalance
     * @description watches information on the user's account balance
     * @see https://docs.kraken.com/exchange/api-reference/futures-websocket/balances
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.account] can be either 'futures' or 'flex_futures'
     * @returns {object} a object of wallet types each with a balance structure {@link https://docs.ccxt.com/?id=balance-structure}
     */
    public java.util.concurrent.CompletableFuture<Object> watchBalance(Object... optionalArgs)
    {

        return java.util.concurrent.CompletableFuture.supplyAsync(() -> {

            Object parameters = Helpers.getArg(optionalArgs, 0, new java.util.HashMap<String, Object>() {{}});
            if (Helpers.isTrue(Helpers.isEqual(this.markets, null)))
            {
                (this.loadMarkets()).join();
            }
            Object name = "balances";
            Object messageHash = name;
            Object account = null;
            var accountparametersVariable = this.handleOptionAndParams(parameters, "watchBalance", "account");
            account = ((java.util.List<Object>) accountparametersVariable).get(0);
            parameters = ((java.util.List<Object>) accountparametersVariable).get(1);
            if (Helpers.isTrue(!Helpers.isEqual(account, null)))
            {
                if (Helpers.isTrue(Helpers.isTrue(!Helpers.isEqual(account, "futures")) && Helpers.isTrue(!Helpers.isEqual(account, "flex_futures"))))
                {
                    throw new ArgumentsRequired((String)Helpers.add(this.id, " watchBalance account must be either 'futures' or 'flex_futures'")) ;
                }
                messageHash = Helpers.add(messageHash, Helpers.add(":", account));
            }
            return (this.subscribePrivate(name, messageHash, parameters)).join();
        });

    }

    public void handleTrade(Client client, Object message)
    {
        //
        // snapshot
        //
        //    {
        //        "feed": "trade_snapshot",
        //        "product_id": "PI_XBTUSD",
        //        "trades": [
        //            {
        //                "feed": "trade",
        //                "product_id": "PI_XBTUSD",
        //                "uid": "caa9c653-420b-4c24-a9f2-462a054d86f1",
        //                "side": "sell",
        //                "type": "fill",
        //                "seq": 655508,
        //                "time": 1612269657781,
        //                "qty": 440,
        //                "price": 34893
        //            },
        //            ...
        //        ]
        //    }
        //
        // update
        //
        //    {
        //        "feed": "trade",
        //        "product_id": "PI_XBTUSD",
        //        "uid": "05af78ac-a774-478c-a50c-8b9c234e071e",
        //        "side": "sell",
        //        "type": "fill",
        //        "seq": 653355,
        //        "time": 1612266317519,
        //        "qty": 15000,
        //        "price": 34969.5
        //    }
        //
        Object channel = this.safeString(message, "feed");
        Object marketId = this.safeString(message, "product_id");
        if (Helpers.isTrue(!Helpers.isEqual(marketId, null)))
        {
            Object market = this.market(marketId);
            Object symbol = Helpers.GetValue(market, "symbol");
            Object messageHash = this.getMessageHash("trade", null, symbol);
            if (Helpers.isTrue(Helpers.isEqual(this.safeList(this.trades, symbol), null)))
            {
                Object tradesLimit = this.safeInteger(this.options, "tradesLimit", 1000);
                Helpers.addElementToObject(this.trades, symbol, new ArrayCache(((Number)tradesLimit).intValue()));
            }
            Object tradesArray = Helpers.GetValue(this.trades, symbol);
            if (Helpers.isTrue(Helpers.isEqual(channel, "trade_snapshot")))
            {
                Object trades = this.safeList(message, "trades", new java.util.ArrayList<Object>(java.util.Arrays.asList()));
                Object length = Helpers.getArrayLength(trades);
                for (var i = 0; Helpers.isLessThan(i, length); i++)
                {
                    Object index = Helpers.subtract(Helpers.subtract(length, 1), i); // need reverse to correct chronology
                    Object item = Helpers.GetValue(trades, index);
                    Object trade = this.parseWsTrade(item);
                    Helpers.callDynamically(tradesArray, "append", new Object[]{trade});
                }
            } else
            {
                Object trade = this.parseWsTrade(message);
                Helpers.callDynamically(tradesArray, "append", new Object[]{trade});
            }
            client.resolve(tradesArray, messageHash);
        }
    }

    public Object parseWsTrade(Object trade, Object... optionalArgs)
    {
        //
        //    {
        //        "feed": "trade",
        //        "product_id": "PI_XBTUSD",
        //        "uid": "caa9c653-420b-4c24-a9f1-462a054d86f1",
        //        "side": "sell",
        //        "type": "fill",
        //        "seq": 655508,
        //        "time": 1612269657781,
        //        "qty": 440,
        //        "price": 34893
        //    }
        //
        // order update
        //     {
        //         "instrument": "PF_DOGEUSD",
        //         "time": 1778610421471,
        //         "last_update_time": 1778610444402,
        //         "qty": 0,
        //         "filled": 10,
        //         "limit_price": 0.10912,
        //         "stop_price": 0,
        //         "type": "limit",
        //         "order_id": "a1c3803c-8f3d-4317-a085-8d06e11b1d36",
        //         "direction": 0,
        //         "reduce_only": false
        //     }
        //
        Object market = Helpers.getArg(optionalArgs, 0, null);
        Object marketId = this.safeString(trade, "product_id");
        market = this.safeMarket(marketId, market);
        Object timestamp = this.safeInteger(trade, "time");
        final Object finalMarket = market;
        return this.safeTrade(new java.util.HashMap<String, Object>() {{
            put( "info", trade );
            put( "id", Krakenfutures.this.safeString(trade, "uid") );
            put( "symbol", Krakenfutures.this.safeString(finalMarket, "symbol") );
            put( "timestamp", timestamp );
            put( "datetime", Krakenfutures.this.iso8601(timestamp) );
            put( "order", null );
            put( "type", Krakenfutures.this.safeString(trade, "type") );
            put( "side", Krakenfutures.this.safeString(trade, "side") );
            put( "takerOrMaker", "taker" );
            put( "price", Krakenfutures.this.safeString2(trade, "price", "limit_price") );
            put( "amount", Krakenfutures.this.safeString2(trade, "filled", "qty") );
            put( "cost", null );
            put( "fee", new java.util.HashMap<String, Object>() {{
                put( "rate", null );
                put( "cost", null );
                put( "currency", null );
            }} );
        }}, market);
    }

