    public Object parseWsTicker(Object ticker, Object... optionalArgs)
    {
        //
        //    {
        //        "time": 1680811086487,
        //        "product_id": "PI_XBTUSD",
        //        "funding_rate": 7.792297e-12,
        //        "funding_rate_prediction": -4.2671095e-11,
        //        "relative_funding_rate": 2.18013888889e-7,
        //        "relative_funding_rate_prediction": -0.0000011974,
        //        "next_funding_rate_time": 1680811200000,
        //        "feed": "ticker",
        //        "bid": 28060,
        //        "ask": 28070,
        //        "bid_size": 2844,
        //        "ask_size": 1902,
        //        "volume": 19628180,
        //        "dtm": 0,
        //        "leverage": "50x",
        //        "index": 28062.14,
        //        "premium": 0,
        //        "last": 28053.5,
        //        "change": -0.7710945651981715,
        //        "suspended": false,
        //        "tag": "perpetual",
        //        "pair": "XBT:USD",
        //        "openInterest": 28875946,
        //        "markPrice": 28064.92082724592,
        //        "maturityTime": 0,
        //        "post_only": false,
        //        "volumeQuote": 19628180
        //    }
        //
        // ticker_lite
        //
        //    {
        //        "feed": "ticker_lite",
        //        "product_id": "FI_ETHUSD_210625",
        //        "bid": 1753.45,
        //        "ask": 1760.35,
        //        "change": 13.448175559936647,
        //        "premium": 9.1,
        //        "volume": 6899673.0,
        //        "tag": "semiannual",
        //        "pair": "ETH:USD",
        //        "dtm": 141,
        //        "maturityTime": 1624633200000,
        //        "volumeQuote": 6899673.0
        //    }
        //
        Object market = Helpers.getArg(optionalArgs, 0, null);
        Object marketId = this.safeString(ticker, "product_id");
        Object marketResolved = this.safeMarket(marketId, market);
        market = marketResolved;
        Object symbol = Helpers.GetValue(marketResolved, "symbol");
        Object timestamp = this.parse8601(this.safeString(ticker, "lastTime"));
        Object last = this.safeString(ticker, "last");
        return this.safeTicker(new java.util.HashMap<String, Object>() {{
            put( "info", ticker );
            put( "symbol", symbol );
            put( "timestamp", timestamp );
            put( "datetime", Krakenfutures.this.iso8601(timestamp) );
            put( "high", null );
            put( "low", null );
            put( "bid", Krakenfutures.this.safeString(ticker, "bid") );
            put( "bidVolume", Krakenfutures.this.safeString(ticker, "bid_size") );
            put( "ask", Krakenfutures.this.safeString(ticker, "ask") );
            put( "askVolume", Krakenfutures.this.safeString(ticker, "ask_size") );
            put( "vwap", null );
            put( "open", null );
            put( "close", last );
            put( "last", last );
            put( "previousClose", null );
            put( "change", Krakenfutures.this.safeString(ticker, "change") );
            put( "percentage", null );
            put( "average", null );
            put( "baseVolume", Krakenfutures.this.safeString(ticker, "volume") );
            put( "quoteVolume", Krakenfutures.this.safeString(ticker, "volumeQuote") );
            put( "markPrice", Krakenfutures.this.safeString(ticker, "markPrice") );
            put( "indexPrice", Krakenfutures.this.safeString(ticker, "index") );
        }});
    }

    public void handleOrderBookSnapshot(Client client, Object message)
    {
        //
        //    {
        //        "feed": "book_snapshot",
        //        "product_id": "PI_XBTUSD",
        //        "timestamp": 1612269825817,
        //        "seq": 326072249,
        //        "tickSize": null,
        //        "bids": [
        //            {
        //                "price": 34892.5,
        //                "qty": 6385
        //            },
        //            {
        //                "price": 34892,
        //                "qty": 10924
        //            },
        //        ],
        //        "asks": [
        //            {
        //                "price": 34911.5,
        //                "qty": 20598
        //            },
        //            {
        //                "price": 34912,
        //                "qty": 2300
        //            },
        //        ]
        //    }
        //
        Object marketId = this.safeString(message, "product_id");
        Object market = this.safeMarket(marketId);
        Object symbol = Helpers.GetValue(market, "symbol");
        Object messageHash = this.getMessageHash("orderbook", null, symbol);
        Object subscription = this.safeDict(client.subscriptions, messageHash, new java.util.HashMap<String, Object>() {{}});
        Object limit = this.safeInteger(subscription, "limit");
        Object timestamp = this.safeInteger(message, "timestamp");
        Helpers.addElementToObject(this.orderbooks, symbol, this.orderBook(new java.util.HashMap<String, Object>() {{}}, limit));
        Object orderbook = Helpers.GetValue(this.orderbooks, symbol);
        Object bids = this.safeList(message, "bids");
        if (Helpers.isTrue(Helpers.isEqual(bids, null)))
        {
            return;
        }
        Object asks = this.safeList(message, "asks");
        if (Helpers.isTrue(Helpers.isEqual(asks, null)))
        {
            return;
        }
        for (var i = 0; Helpers.isLessThan(i, Helpers.getArrayLength(bids)); i++)
        {
            Object bid = Helpers.GetValue(bids, i);
            Object price = this.safeNumber(bid, "price");
            Object qty = this.safeNumber(bid, "qty");
            Object bidsSide = Helpers.GetValue(orderbook, "bids");
            Helpers.callDynamically(bidsSide, "store", new Object[]{price, qty});
        }
        for (var i = 0; Helpers.isLessThan(i, Helpers.getArrayLength(asks)); i++)
        {
            Object ask = Helpers.GetValue(asks, i);
            Object price = this.safeNumber(ask, "price");
            Object qty = this.safeNumber(ask, "qty");
            Object asksSide = Helpers.GetValue(orderbook, "asks");
            Helpers.callDynamically(asksSide, "store", new Object[]{price, qty});
        }
        Helpers.addElementToObject(orderbook, "timestamp", timestamp);
        Helpers.addElementToObject(orderbook, "datetime", this.iso8601(timestamp));
        Helpers.addElementToObject(orderbook, "symbol", symbol);
        client.resolve(orderbook, messageHash);
    }

    public void handleOrderBook(Client client, Object message)
    {
        //
        //    {
        //        "feed": "book",
        //        "product_id": "PI_XBTUSD",
        //        "side": "sell",
        //        "seq": 326094134,
        //        "price": 34981,
        //        "qty": 0,
        //        "timestamp": 1612269953629
        //    }
        //
        Object marketId = this.safeString(message, "product_id");
        Object market = this.safeMarket(marketId);
        Object symbol = Helpers.GetValue(market, "symbol");
        Object messageHash = this.getMessageHash("orderbook", null, symbol);
        Object orderbook = Helpers.GetValue(this.orderbooks, symbol);
        Object side = this.safeString(message, "side");
        Object price = this.safeNumber(message, "price");
        Object qty = this.safeNumber(message, "qty");
        Object timestamp = this.safeInteger(message, "timestamp");
        if (Helpers.isTrue(Helpers.isEqual(side, "sell")))
        {
            Object asks = Helpers.GetValue(orderbook, "asks");
            Helpers.callDynamically(asks, "store", new Object[]{price, qty});
        } else
        {
            Object bids = Helpers.GetValue(orderbook, "bids");
            Helpers.callDynamically(bids, "store", new Object[]{price, qty});
        }
        Helpers.addElementToObject(orderbook, "timestamp", timestamp);
        Helpers.addElementToObject(orderbook, "datetime", this.iso8601(timestamp));
        client.resolve(orderbook, messageHash);
    }

